package com.hms.followups;
import jakarta.persistence.*; import java.time.*; import java.util.UUID;
@Entity @Table(name="follow_ups") public class FollowUp { @Id private UUID id; @Column(nullable=false) private UUID tenantId; @Column(nullable=false) private UUID patientId; private UUID sourceAppointmentId; private UUID doctorId; private LocalDate recommendedFrom; private LocalDate recommendedTo; @Column(nullable=false,length=500) private String reason; @Enumerated(EnumType.STRING) @Column(nullable=false) private FollowUpPriority priority; @Column(length=160) private String responsibleTeam; @Column(length=1000) private String notes; @Enumerated(EnumType.STRING) @Column(nullable=false) private FollowUpStatus status; @Column(nullable=false) private OffsetDateTime createdAt; @Column(nullable=false) private OffsetDateTime updatedAt; protected FollowUp(){} public FollowUp(UUID tenantId,CreateFollowUpRequest r){this.id=UUID.randomUUID();this.tenantId=tenantId;this.patientId=r.patientId();this.sourceAppointmentId=r.sourceAppointmentId();this.doctorId=r.doctorId();this.recommendedFrom=r.recommendedFrom();this.recommendedTo=r.recommendedTo();this.reason=r.reason().trim();this.priority=r.priority();this.responsibleTeam=r.responsibleTeam();this.notes=r.notes();this.status=FollowUpStatus.OPEN;this.createdAt=OffsetDateTime.now();this.updatedAt=createdAt;} public UUID getId(){return id;} public UUID getTenantId(){return tenantId;} public UUID getPatientId(){return patientId;} public UUID getSourceAppointmentId(){return sourceAppointmentId;} public UUID getDoctorId(){return doctorId;} public LocalDate getRecommendedFrom(){return recommendedFrom;} public LocalDate getRecommendedTo(){return recommendedTo;} public String getReason(){return reason;} public FollowUpPriority getPriority(){return priority;} public String getResponsibleTeam(){return responsibleTeam;} public String getNotes(){return notes;} public FollowUpStatus getStatus(){return status;} public void updateStatus(FollowUpStatus s){this.status=s;this.updatedAt=OffsetDateTime.now();} }
